const $=s=>document.querySelector(s); const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n); const veh=id=>vehicles.find(v=>v.id===id); const lead=id=>leadSeeds.find(l=>l.id===id); const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
function toast(t){const e=$('#toast');e.textContent=t;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2200)}
const nav=[['overview','⌂','Overview'],['leads','◎','Leads'],['conversations','▤','Conversations'],['appointments','▦','Appointments'],['inventory','◇','Inventory'],['analytics','▥','Analytics'],['settings','⚙','Settings'],['website','↗','Dealer Website']];
function shell(body,title,sub='Bulldog Motors · Demo workspace'){return `<div class="shell"><aside class="side"><div class="brand"><div class="mark">B</div><div><strong>Bulldog Motors</strong><small>Command Center</small></div></div><nav class="nav">${nav.map(n=>`<button data-page="${n[0]}" class="${state.page===n[0]?'active':''}"><span class="ico">${n[1]}</span>${n[2]}</button>`).join('')}</nav><div class="sidefoot"><div><span class="live-dot"></span>Systems operational</div><div style="margin-top:9px">All figures are demonstration data.</div></div></aside><main><header class="topbar"><div><div class="eyebrow">${esc(sub)}</div><h1>${esc(title)}</h1></div><div class="top-actions"><span class="pill">Wed, Oct 7 · 10:06 AM</span><button class="btn primary" id="run-demo">▶ Run demo</button></div></header><div class="content">${body}</div></main></div>`}
function overview(){const hot=leadSeeds.filter(l=>l.temp==='Hot').slice(0,4);return shell(`<div class="demo-banner"><div><h2>See the complete lead-to-appointment story</h2><p>Marketplace inquiry → live inventory answer → trade capture → confirmed visit → dashboard update</p></div><button class="btn primary" id="banner-demo">Run 3-minute demo</button></div><div class="stats">${[['New leads',8],['Active conversations',12],['Appointments set',4],['Confirmed',3],['Showed',2],['Vehicles sold',1],['Human handoffs',2]].map((x,i)=>`<div class="stat ${i===0||i===6?'hot':''}"><small>${x[0]}</small><strong>${x[1]}</strong><span class="meta">${i<2?'↑ from yesterday':'Today'}</span></div>`).join('')}</div><div class="grid"><section class="card"><div class="card-head"><div><div class="eyebrow">Priority queue</div><h3>Hot leads</h3></div><button class="link" data-page="leads">View all</button></div>${hot.map(l=>{let v=veh(l.vehicleId);return `<div class="lead-row"><div class="avatar">${l.name.split(' ').map(x=>x[0]).join('')}</div><div><b>${l.name}</b><div class="meta">${v.year} ${v.make} ${v.model} · ${l.last}</div></div><span class="temp hot">${l.status}</span></div>`}).join('')}</section><section class="card"><div class="card-head"><div><div class="eyebrow">Operational</div><h3>Today's appointments</h3></div><button class="link" data-page="appointments">Calendar</button></div>${state.appointments.filter(a=>a.day==='Today').map(a=>{let l=lead(a.leadId),v=veh(l.vehicleId);return `<div class="appt-row"><div class="avatar">${a.time.split(':')[0]}</div><div><b>${a.time} · ${l.name}</b><div class="meta">${v.year} ${v.make} ${v.model} · ${a.salesperson}</div></div><span class="badge ${a.status==='Confirmed'?'green':'blue'}">${a.status}</span></div>`}).join('')}</section><section class="card"><div class="card-head"><div><div class="eyebrow">Needs action</div><h3>Follow-ups due</h3></div><span class="badge red">6 due</span></div>${leadSeeds.slice(2,6).map((l,i)=>`<div class="follow-row"><div class="avatar">${i+1}</div><div><b>${l.name}</b><div class="meta">${i?'No reply since yesterday':'Asked about trade, no appointment'}</div></div><button class="btn sm">Review</button></div>`).join('')}</section><section class="card"><div class="card-head"><div><div class="eyebrow">Inventory signals</div><h3>Getting attention</h3></div><button class="link" data-page="inventory">Inventory</button></div>${[16,5,0,12].map(i=>`<div class="lead-row"><div class="avatar">${vehicles[i].leads}</div><div><b>${vehicles[i].year} ${vehicles[i].make} ${vehicles[i].model}</b><div class="meta">${vehicles[i].leads} leads · ${vehicles[i].appointments} appointments</div></div><span class="badge ${vehicles[i].days>50?'red':''}">${vehicles[i].days} days</span></div>`).join('')}</section></div>`,'Today');}
function leads(){return shell(`<div class="section-title"><div><h2>Sales pipeline</h2><p>Every lead, owner, vehicle, trade, and next action in one place.</p></div><button class="btn dark">+ Add lead</button></div><div class="filters"><input placeholder="Search leads"><select><option>All statuses</option><option>Needs Human</option><option>Appointment Set</option></select><select><option>All sources</option><option>Facebook Marketplace</option></select></div><div class="table-wrap"><table><thead><tr><th>Customer</th><th>Vehicle</th><th>Source</th><th>Status</th><th>Owner</th><th>Last contact</th><th>Trade</th></tr></thead><tbody>${leadSeeds.map(l=>{let v=veh(l.vehicleId);return `<tr data-open-convo="${l.id}"><td><b>${l.name}</b><div class="meta">${l.phone}</div></td><td>${v.year} ${v.make} ${v.model}</td><td>${l.source}</td><td><span class="badge ${l.status==='Needs Human'?'red':l.status==='Appointment Set'||l.status==='Sold'?'green':'blue'}">${l.status}</span></td><td>${l.salesperson}</td><td>${l.last}</td><td>${l.trade}</td></tr>`}).join('')}</tbody></table></div>`,'Leads');}
function conversations(){let l=lead(state.selectedLead)||leadSeeds[0],v=veh(l.vehicleId),msgs=state.conversations[l.id]||[{who:'in',text:'Is this still available?',time:'Yesterday'},{who:'out',text:`Yes, the ${v.year} ${v.make} ${v.model} ${v.trim} is currently ${v.status.toLowerCase()}. It has ${v.mileage.toLocaleString()} miles and is listed at ${money(v.price)}. Would today or tomorrow work better?`,time:'Yesterday',label:'Automated assistant'}];return shell(`<div class="split"><aside class="inbox-list">${leadSeeds.map(x=>{let vx=veh(x.vehicleId);return `<div class="inbox-item ${x.id===l.id?'active':''}" data-convo="${x.id}"><b>${x.name}</b><div class="meta">${vx.make} ${vx.model} · ${x.last}</div><div style="margin-top:7px"><span class="badge ${x.status==='Needs Human'?'red':''}">${x.status}</span></div></div>`}).join('')}</aside><section class="thread"><div class="thread-head"><div><b>${l.name}</b><div class="meta">${l.phone} · ${l.source}</div></div><button class="btn sm ${l.status==='Needs Human'?'primary':''}" id="takeover">${l.status==='Needs Human'?'Take over':'Manual takeover'}</button></div><div class="messages">${msgs.map(m=>`<div class="bubble ${m.who}">${esc(m.text)}<small>${m.label||l.name} · ${m.time}</small></div>`).join('')}</div><div class="composer"><input id="message-input" placeholder="Write a message as ${l.salesperson}…"><button class="btn dark" id="send-message">Send</button></div></section><aside class="detail"><div><div class="eyebrow">Lead</div><h3>${l.name}</h3><span class="temp ${l.temp.toLowerCase()}">${l.temp} · ${l.score}</span></div><div class="detail-block"><div class="eyebrow">Interested in</div><h3>${v.year} ${v.make} ${v.model}</h3><div class="kv"><span>Mileage</span><b>${v.mileage.toLocaleString()}</b></div><div class="kv"><span>Price</span><b>${money(v.price)}</b></div><div class="kv"><span>Status</span><b>${v.status}</b></div></div><div class="detail-block"><div class="eyebrow">Trade</div><p>${l.trade}</p></div><div class="detail-block"><div class="eyebrow">Automation</div><p class="meta">Facts come only from structured dealership data. Negotiation, approvals, rates, payments, condition, history, and unknown facts route to a human.</p></div></aside></div>`,'Conversations');}
function appointments(){let days=['Today','Tomorrow','Friday','Saturday','Monday'];return shell(`<div class="section-title"><div><h2>Appointment board</h2><p>Operational schedule with customer, vehicle, owner, trade, and outcome.</p></div><button class="btn dark" id="new-appt">+ Book appointment</button></div><div class="calendar">${days.map(d=>`<div class="day"><h4>${d}</h4>${state.appointments.filter(a=>a.day===d).map(a=>{let l=lead(a.leadId),v=veh(l.vehicleId);return `<div class="event"><b>${a.time} · ${l.name}</b><div class="meta">${v.make} ${v.model}</div><div style="margin-top:7px"><span class="badge ${a.status==='Confirmed'?'green':'blue'}">${a.status}</span></div></div>`}).join('')||'<div class="empty">Open</div>'}</div>`).join('')}</div>`,'Appointments');}
function photo(v,h=140){return `<div class="vehicle-photo ${v.photo?'has-image':''}" style="height:${h}px;${v.photo?`background-image:url('${v.photo}')`:`--c1:#17202a;--c2:#8794a1`}"><span class="badge ${v.status==='Available'?'green':v.status==='Sold'?'red':'blue'}">${v.status}</span>${v.source?'<span class="source-chip">External sample</span>':''}</div>`}
function vehicleCards(list=vehicles){return `<div class="inventory-grid">${list.map(v=>`<article class="vehicle-card" data-vehicle="${v.id}">${photo(v)}<div class="vehicle-body"><h3>${v.year} ${v.make} ${v.model}</h3><div class="meta">${v.trim} · ${v.stock}</div><div class="price">${money(v.price)}</div><div class="specs"><span>${v.mileage.toLocaleString()} mi</span><span>•</span><span>${v.drivetrain}</span><span>•</span><span>${v.days} days</span></div>${v.source?`<div class="market-source">Photo & listing reference: ${v.source}</div>`:''}</div></article>`).join('')}</div>`}
function inventory(){return shell(`<div class="section-title"><div><h2>20 vehicles</h2><p>One structured inventory powers conversations, listings, and the dealer website.</p></div><button class="btn dark">+ Add vehicle</button></div><div class="demo-disclosure"><b>Marketplace samples:</b> Four featured records use current public Cars.com listing references and photography for presentation realism. They are not owned by Bulldog Motors and availability may change.</div><div class="filters"><input id="vehicle-search" placeholder="Search make, model, stock or code"><select id="body-filter"><option value="">All body styles</option>${['Truck','SUV','Sedan','Sports'].map(x=>`<option>${x}</option>`).join('')}</select><span class="pill">18 available · 1 pending · 1 sold</span></div><div id="vehicle-list">${vehicleCards()}</div>`,'Inventory');}
function analytics(){let values=[42,61,78,67,88,94,83];return shell(`<div class="demo-banner"><div><h2>Demo performance snapshot</h2><p>Illustrative data only — not actual Bulldog Motors results.</p></div><span class="badge">Last 30 days</span></div><div class="stats">${[['Median response','38 sec'],['Total leads','184'],['Lead → appointment','31%'],['Appointment → show','68%'],['Show → sale','27%'],['Human takeover','14%'],['Stale leads','19']].map(x=>`<div class="stat"><small>${x[0]}</small><strong>${x[1]}</strong></div>`).join('')}</div><div class="grid"><div class="card"><div class="card-head"><div><div class="eyebrow">Lead volume</div><h3>New leads this week</h3></div></div><div class="chart">${values.map((v,i)=>`<div class="bar ${i===5?'red':''}" style="height:${v}%"><span>${['Thu','Fri','Sat','Sun','Mon','Tue','Wed'][i]}</span></div>`).join('')}</div></div><div class="card"><div class="card-head"><div><div class="eyebrow">Sources</div><h3>Appointments by source</h3></div></div>${[['Facebook Marketplace',18],['Dealer Website',14],['AutoTrader',9],['CarGurus',7],['Walk-in / phone',5]].map(x=>`<div class="lead-row"><div class="avatar">${x[1]}</div><div><b>${x[0]}</b><div class="meta">appointments set</div></div><span class="badge">${Math.round(x[1]/53*100)}%</span></div>`).join('')}</div></div>`,'Analytics');}
function settings(){let ints=[['SMS provider','Simulated','Inbound and outbound text messaging'],['Voice provider','Planned','Shared sales agent for inbound calls'],['Google Calendar','Simulated','Two-way appointment sync'],['Microsoft Calendar','Planned','Two-way appointment sync'],['CRM / DMS','Simulated','Lead, owner, outcome, and inventory sync'],['Inventory feed','Simulated','Vehicle availability and merchandising'],['VIN decoder','Simulated','Structured decode and enrichment'],['Vehicle history','Not connected','Authorized provider only'],['Dealer website','Connected','Same inventory shown to shoppers']];return shell(`<div class="section-title"><div><h2>System connections</h2><p>Adapter-ready architecture. No paid or live third-party dependency is required for this demo.</p></div></div><div class="settings-grid">${ints.map(x=>`<div class="integration"><div class="card-head"><h3>${x[0]}</h3><span class="badge ${x[1]==='Connected'?'green':x[1]==='Not connected'?'red':'blue'}">${x[1]}</span></div><p class="meta">${x[2]}</p><button class="btn sm">Configure</button></div>`).join('')}</div>`,'Settings');}
function website(){return `<div class="website"><header class="topbar" style="background:#0d1117;border-color:#262c34;color:white"><div class="brand" style="padding:0"><div class="mark">B</div><div><strong>Bulldog Motors</strong><small>Athens, Georgia</small></div></div><div class="top-actions"><button class="btn" data-page="overview">Dealer login</button><button class="btn primary">Text (706) 555-0199</button></div></header><section class="sitehero"><div><div class="eyebrow" style="color:#e74b50">Independent. Straightforward. Ready.</div><h2>Find the right car.<br>Drive it today.</h2><p>Browse fresh inventory, get immediate answers, and reserve a test drive without waiting for business hours.</p><div style="display:flex;gap:10px;margin-top:25px"><button class="btn primary" id="browse-cars">Shop inventory</button><button class="btn">Schedule test drive</button></div></div><div class="hero-car has-photo" style="background-image:url('${vehicles[0].photo}')"><span>Marketplace sample · Cars.com</span></div></section><section class="siteinventory" id="site-inventory"><div class="section-title"><div><div class="eyebrow">Available now</div><h2>Featured inventory</h2><p>External marketplace examples power this demo presentation; they are not Bulldog Motors-owned vehicles.</p></div></div>${vehicleCards([vehicles[0],vehicles[1],vehicles[5],vehicles[16],...vehicles.slice(2,6).filter(v=>!v.source)])}</section></div>`}
function render(){let f={overview,leads,conversations,appointments,inventory,analytics,settings,website}[state.page]||overview;$('#app').innerHTML=f();bind()}
function bind(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.page=b.dataset.page;render()});$('#run-demo')?.addEventListener('click',openDemo);$('#banner-demo')?.addEventListener('click',openDemo);document.querySelectorAll('[data-open-convo]').forEach(r=>r.onclick=()=>{state.selectedLead=r.dataset.openConvo;state.page='conversations';render()});document.querySelectorAll('[data-convo]').forEach(r=>r.onclick=()=>{state.selectedLead=r.dataset.convo;render()});document.querySelectorAll('[data-vehicle]').forEach(r=>r.onclick=()=>openVehicle(r.dataset.vehicle));$('#send-message')?.addEventListener('click',sendMessage);$('#takeover')?.addEventListener('click',()=>toast('Conversation assigned to salesperson. Automation paused.'));$('#vehicle-search')?.addEventListener('input',filterVehicles);$('#body-filter')?.addEventListener('change',filterVehicles);$('#browse-cars')?.addEventListener('click',()=>$('#site-inventory').scrollIntoView({behavior:'smooth'}));}
function filterVehicles(){let q=($('#vehicle-search').value||'').toLowerCase(),b=$('#body-filter').value;let list=vehicles.filter(v=>(!b||v.body===b)&&(`${v.year} ${v.make} ${v.model} ${v.stock} ${v.code}`.toLowerCase().includes(q)));$('#vehicle-list').innerHTML=vehicleCards(list);document.querySelectorAll('[data-vehicle]').forEach(r=>r.onclick=()=>openVehicle(r.dataset.vehicle))}
function sendMessage(){let input=$('#message-input');if(!input.value.trim())return;let id=state.selectedLead;state.conversations[id]=state.conversations[id]||[];state.conversations[id].push({who:'human',text:input.value.trim(),time:'Now',label:lead(id).salesperson});render();toast('Message added to demo transcript')}
function openVehicle(id){let v=veh(id);state.selectedVehicle=id;let listing=`${v.year} ${v.make} ${v.model} ${v.trim} — ${money(v.price)}\n\n${v.description} Finished in ${v.color} with ${v.interior} interior, ${v.drivetrain}, ${v.transmission}, and ${v.engine}. ${v.mileage.toLocaleString()} miles. Major features include ${v.features.join(', ')}.\n\nInterested? Text ${v.code} to (706) 555-0199 for availability or to schedule a test drive.`;showModal(`<div class="modal-head"><div><div class="eyebrow">${v.stock} · ${v.status}</div><h2 style="margin:3px 0">${v.year} ${v.make} ${v.model} ${v.trim}</h2></div><button class="btn" data-close>✕</button></div><div class="modal-body"><div class="grid"><div>${photo(v,260)}${v.source?`<div class="source-panel"><b>External marketplace sample</b><br>${v.source}<br><a href="${v.sourceUrl}" target="_blank" rel="noopener">View original listing ↗</a></div>`:''}<div class="stats" style="grid-template-columns:repeat(3,1fr);margin-top:14px"><div class="stat"><small>Price</small><strong style="font-size:20px">${money(v.price)}</strong></div><div class="stat"><small>Mileage</small><strong style="font-size:20px">${v.mileage.toLocaleString()}</strong></div><div class="stat"><small>Leads</small><strong style="font-size:20px">${v.leads}</strong></div></div><p class="meta">VIN ${v.vin} · ${v.color} / ${v.interior} · ${v.drivetrain} · ${v.transmission}</p><p><span class="badge red">DEMO HISTORY DATA</span> ${v.history}</p></div><div><div class="eyebrow">Generated listing</div><h3>Ready to copy and post</h3><textarea id="listing" style="width:100%;height:300px;border:1px solid var(--line);border-radius:12px;padding:14px;line-height:1.5">${esc(listing)}</textarea><button class="btn primary" id="copy-listing" style="margin-top:10px">Copy listing</button></div></div></div>`);$('#copy-listing').onclick=async()=>{await navigator.clipboard?.writeText($('#listing').value);toast('Listing copied')};}
function showModal(html){let m=document.createElement('div');m.className='modal';m.innerHTML=`<div class="modal-card">${html}</div>`;document.body.appendChild(m);m.onclick=e=>{if(e.target===m||e.target.closest('[data-close]'))m.remove()}}
const demoSteps=[
['Marketplace listing',`<div class="vehicle-card" style="max-width:370px;margin:35px auto">${photo(vehicles[0],190)}<div class="vehicle-body"><div class="market-source">External sample reference · Cars.com</div><h3>2021 Ford F-150 XLT</h3><div class="price">$34,838</div><p class="meta">29,135 miles · Agate Black Metallic · 4WD</p><b>Text F150 to (706) 555-0199</b></div></div>`],
['Buyer inquiry',`<div class="phone"><div class="phone-top">Bulldog Motors</div><div class="phone-chat"><div class="bubble">F150<small>Buyer · now</small></div></div></div>`],
['Instant inventory answer',`<div class="phone"><div class="phone-top">Bulldog Motors</div><div class="phone-chat"><div class="bubble">F150</div><div class="bubble out">The external marketplace sample shows a 2021 Ford F-150 XLT with 29,135 miles at $34,838. We’ll verify availability before your visit. Today or tomorrow?</div></div></div>`],
['Natural question',`<div class="phone"><div class="phone-top">Bulldog Motors</div><div class="phone-chat"><div class="bubble">How many miles and is it 4x4?</div><div class="bubble out">The referenced listing shows 29,135 miles and four-wheel drive.</div></div></div>`],
['Trade captured',`<div class="phone"><div class="phone-top">Bulldog Motors</div><div class="phone-chat"><div class="bubble">I have a 2015 Silverado with 128k to trade.</div><div class="bubble out">We take trades. I’ve noted it for an in-person appraisal; no value has been promised.</div></div></div>`],
['Appointment offered',`<div class="phone"><div class="phone-top">Bulldog Motors</div><div class="phone-chat"><div class="bubble out">We can have the F-150 ready today at 2:30 PM or 4:00 PM. Which works better?</div></div></div>`],
['Buyer chooses',`<div class="phone"><div class="phone-top">Bulldog Motors</div><div class="phone-chat"><div class="bubble">4 works</div></div></div>`],
['Appointment booked',`<div class="phone"><div class="phone-top">Bulldog Motors</div><div class="phone-chat"><div class="bubble out">Confirmed for today at 4:00 PM with Jordan Ellis. We’ll have the F-150 ready.</div></div></div>`],
['Salesperson notified',`<div class="card" style="max-width:480px;margin:70px auto"><div class="eyebrow">New appointment</div><h2>4:00 PM · Marcus Hill</h2><p>2021 Ford F-150 XLT</p><div class="detail-block"><b>Trade</b><p>2015 Chevrolet Silverado · 128,000 miles</p></div><span class="badge green">Jordan Ellis notified</span></div>`],
['Dashboard updated',`<div class="card" style="max-width:560px;margin:55px auto"><div class="eyebrow">Live pipeline event</div><h2>Lead → Appointment Set</h2><div class="stats" style="grid-template-columns:repeat(3,1fr)"><div class="stat hot"><small>Appointments</small><strong>5</strong></div><div class="stat"><small>Confirmed</small><strong>4</strong></div><div class="stat"><small>Response</small><strong>&lt;1m</strong></div></div><p class="meta">The transcript, vehicle, trade, owner, and appointment are connected in one record.</p></div>`]
];
function openDemo(){state.demo=0;demoModal()}
function demoModal(){document.querySelector('.modal')?.remove();let i=state.demo;showModal(`<div class="modal-head"><div><div class="eyebrow">Guided demo · Step ${i+1} of 10</div><h2 style="margin:3px 0">${demoSteps[i][0]}</h2></div><button class="btn" data-close>✕</button></div><div class="modal-body"><div class="demo-layout"><div class="steps">${demoSteps.map((x,j)=>`<div class="step ${j<i?'done':j===i?'active':''}">${j<i?'✓':j+1} · ${x[0]}</div>`).join('')}</div><div><div style="min-height:580px;display:grid;align-items:center">${demoSteps[i][1]}</div><div class="demo-controls"><button class="btn" id="demo-back" ${i===0?'disabled':''}>Back</button><button class="btn primary" id="demo-next">${i===9?'Finish demo':'Next step →'}</button></div></div></div></div>`);$('#demo-back').onclick=()=>{state.demo--;demoModal()};$('#demo-next').onclick=()=>{if(state.demo===9){document.querySelector('.modal').remove();state.page='overview';render();toast('Demo complete — appointment and dashboard are synchronized')}else{state.demo++;demoModal()}}}
render();
